import { ChangeDetectorRef, Component, ElementRef } from '@angular/core';
import { inject, viewChild } from '@angular/core';

@Component({ selector: 'app-inbox', templateUrl: './inbox.html' })
export class Inbox {
  private readonly cdr = inject(ChangeDetectorRef);
  private readonly list = viewChild.required<ElementRef<HTMLElement>>('list');
  messages: Message[] = [];

  constructor() {
    inject(ChatSocket).messages$.subscribe((m) => {
      this.messages = [...this.messages, m];
      this.cdr.detectChanges(); // renders Inbox right now, once per message
      this.list().nativeElement.lastElementChild?.scrollIntoView();
    });
  }
}

import { Component, ElementRef, afterRenderEffect } from '@angular/core';
import { inject, viewChild } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { scan } from 'rxjs';

@Component({ selector: 'app-inbox', templateUrl: './inbox.html' })
export class Inbox {
  private readonly list = viewChild.required<ElementRef<HTMLElement>>('list');
  readonly messages = toSignal(
    inject(ChatSocket).messages$.pipe(
      scan((all: Message[], m) => [...all, m], []),
    ),
    { initialValue: [] },
  );

  constructor() {
    // Runs after the DOM is updated, each time messages() has changed
    afterRenderEffect({
      write: () => {
        this.messages(); // the dependency that re-runs this callback
        this.list().nativeElement.lastElementChild?.scrollIntoView();
      },
    });
  }
}
